def populate_slugs_and_prepare_studio_records(apps, schema_editor):
    ProfessionalProfile = apps.get_model('core', 'ProfessionalProfile')
    StudioAbout = apps.get_model('core', 'StudioAbout')
    TeamMember = apps.get_model('core', 'TeamMember')

    used_slugs = set(
        ProfessionalProfile.objects.exclude(slug__isnull=True)
        .exclude(slug='')
        .values_list('slug', flat=True)
    )

    for profile in ProfessionalProfile.objects.order_by('id'):
        if profile.slug:
            used_slugs.add(profile.slug)
            continue
        base_slug = (slugify(profile.name) or f'estudio-{profile.id}')[:90]
        candidate = base_slug
        counter = 2
        while candidate in used_slugs:
            candidate = f'{base_slug}-{counter}'
            counter += 1
        profile.slug = candidate
        profile.save(update_fields=['slug'])
        used_slugs.add(candidate)

    default_profile = ProfessionalProfile.objects.order_by('id').first()
    if default_profile is not None:
        StudioAbout.objects.filter(profile__isnull=True).update(profile=default_profile)
        TeamMember.objects.filter(profile__isnull=True).update(profile=default_profile)
    else:
        StudioAbout.objects.filter(profile__isnull=True).delete()
        TeamMember.objects.filter(profile__isnull=True).delete()

    # Asegurar unicidad de StudioAbout por profile antes de aplicar UniqueConstraint
    profile_ids = (
        StudioAbout.objects.values_list('profile_id', flat=True).distinct()
    )
    for pid in profile_ids:
        abouts = list(StudioAbout.objects.filter(profile_id=pid).order_by('-updated_at', '-id'))
        if len(abouts) > 1:
            ids_to_delete = [item.id for item in abouts[1:]]
            StudioAbout.objects.filter(id__in=ids_to_delete).delete()


